window.docContents[154].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Notation-for-algebraic-numbers-and-algebraic-integers/#Chapter5___Discussion_after_Proposition5___2___3":{"contents":"The set of algebraic numbers is denoted by \\overline{\\mathbb{Q}}, and the set of algebraic integers is denoted by \\overline{\\mathbb{Z}}.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.2. Algebraic numbers and algebraic integers\tNotation for algebraic numbers and algebraic integers","header":"Notation for algebraic numbers and algebraic integers","id":"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Notation-for-algebraic-numbers-and-algebraic-integers/#Chapter5___Discussion_after_Proposition5___2___3"},"/3___-General-results-of-representation-theory/3___3___-Representations-of-direct-sums-of-matrix-algebras/Section-3___3___-Representations-of-direct-sums-of-matrix-algebras-___-heading-and-setup/#Chapter3___Introduction_to_3___3___heading-1":{"contents":"In this section we consider representations of algebras A = \\bigoplus_i \\operatorname{Mat}_{d_i}(k) for any field k.\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.3. Representations of direct sums of matrix algebras\tSection 3.3: Representations of direct sums of matrix algebras — heading and setup","header":"3.3. Representations of direct sums of matrix algebras","id":"/3___-General-results-of-representation-theory/3___3___-Representations-of-direct-sums-of-matrix-algebras/Section-3___3___-Representations-of-direct-sums-of-matrix-algebras-___-heading-and-setup/#Chapter3___Introduction_to_3___3___heading-1"},"/5___-Representations-of-finite-groups___-Further-results/5___16___-Problems/Section-5___16___-Problems-on-Young-diagrams-and-branching-rules/#Chapter5___Introduction_5___16":{"contents":"\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.16. Problems\tSection 5.16: Problems on Young diagrams and branching rules","header":"Section 5.16: Problems on Young diagrams and branching rules","id":"/5___-Representations-of-finite-groups___-Further-results/5___16___-Problems/Section-5___16___-Problems-on-Young-diagrams-and-branching-rules/#Chapter5___Introduction_5___16"},"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Corollary-6___8___3___-Uniqueness-of-indecomposable-with-given-dimension-vector/#Chapter6___Corollary6___8___3":{"contents":"Corollary 6.8.3. Let V, V' be indecomposable representations of Q such that d(V) = d(V'). Then V and V' are isomorphic.\nProof. Let i be the smallest integer such that\n\n\nd\\left(V^{(i)}\\right) = \\alpha_p.\n\n\nThen we also get d\\left(V'^{(i)}\\right) = \\alpha_p. So\n\n\nV'^{(i)} = V^{(i)} =: V^i.\n\n\nFurthermore we have\n\n\nV^{(i)} = F_k^+ \\ldots F_{n-1}^+ F_n^+ V^{(0)},\n\n\n\nV'^{(i)} = F_k^+ \\ldots F_{n-1}^+ F_n^+ V'^{(0)}.\n\n\nBut both V^{(i-1)}, \\ldots, V^{(0)} and V'^{(i-1)}, \\ldots, V'^{(0)} have to be surjective at the appropriate vertices. This implies\n\n\nF_n^- F_{n-1}^- \\ldots F_k^- V^i = \\begin{cases} F_n^- F_{n-1}^- \\ldots F_k^- F_k^+ \\ldots F_{n-1}^+ F_n^+ V^{(0)} = V^{(0)} = V, \\\\ F_n^- F_{n-1}^- \\ldots F_k^- F_k^+ \\ldots F_{n-1}^+ F_n^+ V'^{(0)} = V'^{(0)} = V'. \\end{cases}\n\n\n\\square\n\n\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.8. Proof of Gabriel's theorem\tCorollary 6.8.3: Uniqueness of indecomposable with given dimension vector","header":"Corollary 6.8.3: Uniqueness of indecomposable with given dimension vector","id":"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Corollary-6___8___3___-Uniqueness-of-indecomposable-with-given-dimension-vector/#Chapter6___Corollary6___8___3"},"/8___-Homological-algebra/8___2___-Tor-and-Ext-functors/Section-8___2___-Tor-and-Ext-functors/#Chapter8___Introduction_8___2":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\t8. Homological algebra\t8.2. Tor and Ext functors\tSection 8.2: Tor and Ext functors","header":"Section 8.2: Tor and Ext functors","id":"/8___-Homological-algebra/8___2___-Tor-and-Ext-functors/Section-8___2___-Tor-and-Ext-functors/#Chapter8___Introduction_8___2"}});
